(function(root){
'use strict';
const catalog={
'Stale application':{area:'Pipeline health',impact:'Slow candidate progression increases drop-off risk and obscures bottlenecks.',hypothesis:'Stage ownership or follow-up cadence may be unclear.',fix:'Introduce stage-age alerts and weekly recruiter pipeline reviews.',owner:'Recruiting Operations',effort:2,metric:'Active applications beyond stage SLA below 10%',phase:1},
'Missing rejection reason':{area:'Data quality',impact:'Funnel exit reporting becomes incomplete.',hypothesis:'Disposition fields may not be enforced at closure.',fix:'Standardise disposition categories and monitor closure completeness.',owner:'ATS Administrator',effort:2,metric:'At least 95% of rejected applications have a reason',phase:1},
'Possible duplicate':{area:'Data quality',impact:'Duplicate records distort funnel volumes and create conflicting candidate histories.',hypothesis:'Import and reapplication workflows may lack duplicate review.',fix:'Review matches manually and define deduplication governance; never auto-merge.',owner:'Recruiting Operations',effort:3,metric:'Reviewed duplicate flags per month',phase:2},
'Inactive open role':{area:'Pipeline health',impact:'Open requisitions may lack momentum or have incomplete activity capture.',hypothesis:'Requisition status and weekly activity reviews may be misaligned.',fix:'Review requisition ownership, activity coverage and paused-role status.',owner:'Talent Acquisition Lead',effort:2,metric:'Open roles with no recent application activity',phase:1},
'Missing core values':{area:'Reporting readiness',impact:'Incomplete identifiers and statuses undermine trustworthy metrics.',hypothesis:'Import mapping or required-field validation may be incomplete.',fix:'Validate required fields at ingestion and backfill verified records.',owner:'ATS Administrator',effort:2,metric:'Core-field completeness at least 99%',phase:1},
'Invalid date':{area:'Reporting readiness',impact:'Incorrect timestamps undermine time-based recruiting metrics.',hypothesis:'Multiple date formats may be entering the export.',fix:'Standardise ISO timestamps and validate exports.',owner:'People Analytics',effort:2,metric:'Invalid date rate below 1%',phase:1},
'Missing stage date':{area:'Process consistency',impact:'Stage waiting times cannot be reliably measured.',hypothesis:'Stage-transition timestamps may be missing from exports.',fix:'Audit stage-transition tracking and required report fields.',owner:'ATS Administrator',effort:2,metric:'Stage timestamp coverage at least 99%',phase:2},
'Status / interview conflict':{area:'Process consistency',impact:'Candidates may receive inconsistent communications.',hypothesis:'Interview cancellation may not follow terminal status transitions.',fix:'Review status-change automation and pending interview cancellation.',owner:'Recruiting Operations',effort:2,metric:'Zero terminal-status future-interview conflicts',phase:1},
'Future historical date':{area:'Reporting readiness',impact:'Future-dated activity distorts process duration.',hypothesis:'Timestamp timezone or export mapping may be wrong.',fix:'Review source timestamps and date parsing.',owner:'People Analytics',effort:1,metric:'Zero future historical timestamps',phase:1},
'Unrecognised status':{area:'Process consistency',impact:'Unmapped statuses make funnel denominators unreliable.',hypothesis:'Custom statuses may lack an agreed reporting taxonomy.',fix:'Define and publish a canonical application status mapping.',owner:'Recruiting Operations',effort:2,metric:'100% of statuses mapped',phase:2}
};
const extra=[
{name:'Candidate source completeness',keys:['Candidate source','Source'],area:'Data quality',rule:'Missing candidate source',check:r=>!r.source,impact:'Source attribution and channel effectiveness cannot be assessed.',hypothesis:'Source capture may not be mandatory.',fix:'Define source taxonomy and review attribution completeness.',owner:'Talent Acquisition Operations',effort:2,metric:'At least 95% of applications have source',phase:2},
{name:'Interview feedback timeliness',keys:['Feedback submitted at','Interview completed at'],area:'Process consistency',rule:'Late or missing interview feedback',impact:'Late feedback delays hiring decisions.',hypothesis:'Interviewers may lack reminders or SLAs.',fix:'Set a 48-hour feedback SLA and automated reminders.',owner:'Interview Programme Owner',effort:3,metric:'At least 90% of feedback within 48 hours',phase:2}
];
function analyse(result,parsed,map){const issues=[...result.issues];const headers=parsed.headers;const get=(r,k)=>{let i=headers.indexOf(k);return i<0?'':String(parsed.rows[r.row-2][i]||'').trim();};
const sourceCol=headers.find(h=>/^(candidate source|source)$/i.test(h));
if(sourceCol)result.records.forEach(r=>{if(!get(r,sourceCol))issues.push({key:'source:'+r.row,row:r.row,id:r.id,candidate:r.candidate,job:r.job,rule:'Missing candidate source',severity:'Medium',evidence:'Candidate source is blank.',action:extra[0].fix,scope:'application'});});
const feedbackCol=headers.find(h=>/^feedback submitted at$/i.test(h)),interviewCol=headers.find(h=>/^interview completed at$/i.test(h));
if(feedbackCol&&interviewCol)result.records.forEach(r=>{let interview=Health.date(get(r,interviewCol)),submitted=Health.date(get(r,feedbackCol));if(!interview||interview>Health.date(result.asOf))return;let delta=submitted?(submitted-interview)/86400000:null;if(delta===null||delta>2)issues.push({key:'feedback:'+r.row,row:r.row,id:r.id,candidate:r.candidate,job:r.job,rule:'Late or missing interview feedback',severity:'Medium',evidence:delta===null?'No feedback submission timestamp.':'Feedback submitted '+delta.toFixed(1)+' days after interview.',action:extra[1].fix,scope:'application'});});
const stageGroups=new Map();result.records.forEach(r=>{if(!r.job||!r.stage)return;let key=r.jobId||r.job;if(!stageGroups.has(key))stageGroups.set(key,new Set());stageGroups.get(key).add(r.stage.toLowerCase());});
const stageCoverage=stageGroups.size;
const unsupported=[!sourceCol?'Candidate source completeness':null,!(feedbackCol&&interviewCol)?'Interview feedback timeliness':null,'Stage configuration consistency (requires job-level stage configuration)','Time-to-fill (requires requisition open and close dates)'].filter(Boolean);
const grouped=Object.values(issues.reduce((a,i)=>{if(!a[i.rule])a[i.rule]={rule:i.rule,items:[],severity:i.severity};a[i.rule].items.push(i);if(i.severity==='High')a[i.rule].severity='High';return a;},{}));
const severityWeight={High:3,Medium:2,Low:1};grouped.forEach(g=>{g.meta=catalog[g.rule]||extra.find(x=>x.rule===g.rule)||{area:'Reporting readiness',impact:'Data reliability is reduced.',hypothesis:'Workflow configuration may need review.',fix:g.items[0].action,owner:'Recruiting Operations',effort:2,metric:'Reduce affected records',phase:2};g.priority=severityWeight[g.severity]*10+Math.min(g.items.length,20)*2+(g.meta.area==='Pipeline health'?5:0)-g.meta.effort*2;});grouped.sort((a,b)=>b.priority-a.priority);
const areas=['Pipeline health','Data quality','Process consistency','Reporting readiness'];const scores=Object.fromEntries(areas.map(area=>{let scoped=issues.filter(i=>(catalog[i.rule]||extra.find(x=>x.rule===i.rule)||{}).area===area);let penalty=scoped.reduce((n,i)=>n+severityWeight[i.severity],0);return[area,Math.max(0,Math.round(100-100*penalty/Math.max(1,result.records.length*3)))];}));
const available={ 'Pipeline health':true,'Data quality':true,'Process consistency':true,'Reporting readiness':true};const score=Math.round(areas.reduce((s,a)=>s+scores[a],0)/4);
return{issues,grouped,scores,score,unsupported,stageCoverage,method:'Each category starts at 100; subtract 100 × sum of finding weights (High 3, Medium 2, Low 1) ÷ (3 × application count), floored at zero. Overall is the unweighted mean of four category scores. These are illustrative issue-density indices, not validated industry benchmarks. Missing checks do not count as passed.',asOf:result.asOf};}
function queue(model){return Health.csv([['Priority','Issue type','Scope','Application ID','CSV row','Candidate','Role','Evidence','Recommended action','Suggested owner'],...model.grouped.flatMap(g=>g.items.map(i=>[i.severity,i.rule,i.scope,i.id,i.row,i.candidate,i.job,i.evidence,g.meta.fix,g.meta.owner]))]);}
const api={analyse,queue,catalog};if(typeof module!=='undefined')module.exports=api;root.Ops=api;
})(typeof window!=='undefined'?window:globalThis);